template:
use std::ops::Add;

#[derive(Debug, PartialEq, Clone)]
struct Score(i32);

impl Add for ⟦slot1⟧ {
    type Output = Score;
    fn add(self, rhs: &Score) -> Score {
        Score(self.0 + rhs.0)
    }
}

fn main() {
    let s1 = Score(10);
    let s2 = Score(20);
    let total = ⟦slot2⟧ + &s2;
    assert_eq!(total, Score(30));
    assert_eq!(s1, Score(10));
}

tests:
#[test]
fn test_score_add() {
    let a = Score(5);
    let b = Score(15);
    let c = &a + &b;
    assert_eq!(c, Score(20));
    assert_eq!(a, Score(5));
}
